import "server-only";

import { readFileSync } from "node:fs";
import path from "node:path";

import { migrate } from "drizzle-orm/node-postgres/migrator";

import { getDb } from "./client.ts";

// Applies the SQL migrations in drizzle/ (generated by `pnpm db:generate`, committed) on first use:
// locally, in scripts and in production (the Dockerfile copies drizzle/). Migrations are additive
// only, so an older image still works after a rollback.
//
// Outside production the journal is re-read (at most every 2 s), so a migration that arrives with
// `git pull` while `pnpm dev` is running is applied on the next request, without a restart.

const MIGRATIONS_FOLDER = path.join(process.cwd(), "drizzle");
const JOURNAL = path.join(MIGRATIONS_FOLDER, "meta", "_journal.json");
const RECHECK_MS = 2_000;
const RECHECK = process.env.NODE_ENV !== "production";

let ready: Promise<void> | undefined;
let failed = false;
let migratedCount = -1;
let checkedAt = 0;

function journalCount(): number {
  try {
    return (JSON.parse(readFileSync(JOURNAL, "utf8")) as { entries: unknown[] }).entries.length;
  } catch {
    return migratedCount; // unreadable (e.g. mid-checkout): keep what we have
  }
}

function newMigrations(): boolean {
  if (!RECHECK || Date.now() - checkedAt < RECHECK_MS) return false;
  checkedAt = Date.now();
  return journalCount() > migratedCount;
}

async function run(): Promise<void> {
  checkedAt = Date.now();
  const count = journalCount();
  await migrate(getDb(), { migrationsFolder: MIGRATIONS_FOLDER });
  migratedCount = count;
}

/** Brings the database schema up to date. A failure is retried on the next call. */
export function ensureDatabase(): Promise<void> {
  if (!ready || failed || newMigrations()) {
    failed = false;
    // Chained after the previous run, so migrations never run twice at once in this process.
    const previous = ready?.catch(() => {}) ?? Promise.resolve();
    ready = previous.then(run).catch((err: unknown) => {
      failed = true;
      throw err;
    });
  }
  return ready;
}
